    }).join('');
    var recent = d.recent_sales || [];
    var body =
      '<div class="omov-detail-grid">' +
        '<div class="omov-detail-block"><div class="omov-detail-block-label">Total Sales</div><div class="omov-detail-block-val" style="color:var(--c-green)">' + fmt(d.total_sales) + '</div></div>' +
        '<div class="omov-detail-block"><div class="omov-detail-block-label">Period</div><div class="omov-detail-block-val">' + (d.period_label || '—') + '</div></div>' +
      '</div>' +
      (typeRows ? '<div class="omov-section-divider">By Invoice Type</div><div class="omov-detail-grid">' + typeRows + '</div>' : '') +
      (payRows  ? '<div class="omov-section-divider">By Payment Type</div><div class="omov-detail-grid">' + payRows + '</div>' : '') +
      '<div class="omov-section-divider">Recent Invoices</div>' +
      recent.map(function (inv) {
        var itBg = INV_TYPE_COLORS[inv.custom_invoice_type] || 'var(--c-blue)';
        var ptCls = { 'CREDIT':'pt-credit','CASH':'pt-cash','WARRANTY':'pt-warranty','INSURANCE':'pt-insurance' }[inv.custom_payment_type] || 'pt-credit';
        return '<div class="omov-list-row omov-sinv-row" data-name="' + inv.name + '"><div><div class="omov-list-name">' + inv.name + '</div><div class="omov-list-sub">' + (inv.customer_name || '—') + ' · ' + (inv.posting_date || '') + '</div>' +
          (inv.custom_invoice_type ? '<span class="omov-inv-type-badge" style="background:' + itBg + '1a;color:' + itBg + '">' + inv.custom_invoice_type + '</span>' : '') +
          (inv.custom_payment_type ? '<span class="omov-pay-type-badge ' + ptCls + '">' + inv.custom_payment_type + '</span>' : '') +
          '</div><div class="omov-list-right"><div class="omov-list-val" style="color:var(--c-green)">' + fmt(inv.grand_total) + '</div></div></div>';
      }).join('') || '<div class="omov-loader">No invoices</div>';
    openModal('Total Sales', fmt(d.total_sales) + ' · ' + (d.period_label || ''), body, '<button class="omov-open-btn" id="omov-open-sinv-modal">Open Sales Invoices ↗</button>');
    setTimeout(function () {
      var btn = q('#omov-open-sinv-modal');
      if (btn) btn.addEventListener('click', function () { closeModal(); frappe.set_route('List', 'Sales Invoice'); });
      bindModalRows('.omov-sinv-row', 'Sales Invoice');
    }, 50);
  };

