  var refresh = function () {
    var btn = q('#omovRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);
    var args = { period: currentPeriod };
    if (currentPeriod === 'custom' && customDateFrom && customDateTo) {
      args.date_from = customDateFrom;
      args.date_to   = customDateTo;
    }
    frappe.call({
      method: 'omeir_motors.omeir_motors.api.overview_dashboard.get_overview_dashboard_data',
      args: args,
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load data.', indicator: 'red' });
          setLoading(false);
          return;
        }
        dashData = r.message;
        populateKPIs(dashData);
        populateBalances(dashData);
        populatePayables(dashData);
        populateInvTypeList(dashData.sales_by_inv_type);
        populatePayTypeList(dashData.sales_by_pay_type);
        populateRecentSales(dashData.recent_sales);
        populateRecentPurchase(dashData.recent_purchases);
        populateOverdueRec(dashData.overdue_receivables);
        populateOverduePay(dashData.overdue_payables);
        setLoading(false);
        loadChartJS(function () {
          buildSalesChart(dashData.monthly_sales_purchase);
        });
      }
    });
  };

