      applyBtn.addEventListener('click', function () {
        if (!fromEl || !toEl || !fromEl.value || !toEl.value) {
          frappe.msgprint({ title: 'Date Required', message: 'Please select both From and To dates for the chart.', indicator: 'orange' });
          return;
        }
        chartDateFrom = fromEl.value;
        chartDateTo   = toEl.value;
        buildSalesChart(chartMonthlyData);
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', function () {
        chartDateFrom = '';
        chartDateTo   = '';
        if (fromEl) fromEl.value = '';
        if (toEl)   toEl.value   = '';
        buildSalesChart(chartMonthlyData);
      });
    }
  };

  loadTheme();
  setDate();
  attachListeners();
  attachChartFilters();
  refresh();

})();

style:
@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&family=JetBrains+Mono:wght@400;500;600&display=swap');

.om-ov-dash {
  --bg: #f5f4f0;
  --surface: #ffffff;
  --surface2: #f9f8f5;
  --border: #e8e5dc;
  --border-md: #d4cfc2;
  --text-1: #1c1a16;
  --text-2: #5a5548;
  --text-3: #9e9785;
  --c-gold: #b8860b;      --c-gold-bg: #fef9ec;
  --c-blue: #1a4fa3;      --c-blue-bg: #eef3fc;
  --c-green: #1a7a4a;     --c-green-bg: #edf8f2;
  --c-red: #9b1c1c;       --c-red-bg: #fef2f2;
  --c-teal: #0f6b6b;      --c-teal-bg: #edfafa;
  --c-violet: #5b21b6;    --c-violet-bg: #f5f3ff;
  --c-amber: #92400e;     --c-amber-bg: #fffbeb;
  --c-slate: #374151;     --c-slate-bg: #f8fafc;
  --shadow: 0 1px 3px rgba(28,26,22,0.08), 0 0 0 1px var(--border);
  --shadow-hover: 0 8px 24px rgba(28,26,22,0.12), 0 0 0 1px var(--border-md);
  --radius: 12px;
  --radius-sm: 8px;
  font-family: 'Instrument Sans', sans-serif;
  background: var(--bg);
  color: var(--text-1);
  padding: 28px 24px;
  min-height: 100vh;
  overflow-x: hidden;
  box-sizing: border-box;
  transition: background 0.3s, color 0.3s;
}

.om-ov-dash *, .om-ov-dash *::before, .om-ov-dash *::after { box-sizing: border-box; }

.om-ov-dash.dark {
  --bg: #0e0d0b;
  --surface: #161510;
  --surface2: #1d1c17;
  --border: #2a2820;
  --border-md: #38352a;
  --text-1: #f0ece2;
  --text-2: #8a8370;
  --text-3: #4e4a3c;
  --c-gold: #d4a017;      --c-gold-bg: rgba(212,160,23,0.12);
  --c-blue: #4d80d0;      --c-blue-bg: rgba(77,128,208,0.12);
  --c-green: #2ea860;     --c-green-bg: rgba(46,168,96,0.12);
  --c-red: #e05252;       --c-red-bg: rgba(224,82,82,0.12);
  --c-teal: #2ab8b8;      --c-teal-bg: rgba(42,184,184,0.12);
  --c-violet: #9d6ff0;    --c-violet-bg: rgba(157,111,240,0.12);
  --c-amber: #f0a030;     --c-amber-bg: rgba(240,160,48,0.12);
  --c-slate: #94a3b8;     --c-slate-bg: rgba(148,163,184,0.10);
  --shadow: 0 1px 4px rgba(0,0,0,0.4), 0 0 0 1px var(--border);
  --shadow-hover: 0 8px 28px rgba(0,0,0,0.45), 0 0 0 1px var(--border-md);
}

/* ── Header ── */
.omov-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 14px;
}

.omov-title-block {}

.omov-eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--c-gold);
  text-transform: uppercase;
  display: block;
  margin-bottom: 5px;
}

.omov-title {
  font-family: 'Instrument Serif', serif;
  font-size: 26px;
  font-weight: 400;
  color: var(--text-1);
  margin: 0;
  letter-spacing: -0.01em;
  line-height: 1;
}

.omov-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.omov-date {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-3);
}

.omov-period-select {
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 500;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-2);
  padding: 6px 10px;
  border-radius: 7px;
  cursor: pointer;
  outline: none;
  transition: border-color 0.2s;
}
.omov-period-select:focus { border-color: var(--c-gold); }

.omov-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-2);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.18s;
}
.omov-btn:hover { border-color: var(--c-gold); color: var(--c-gold); }

.omov-date-range { display: flex; align-items: center; gap: 6px; }
.omov-date-input {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-1);
  padding: 5px 8px;
  border-radius: 7px;
  outline: none;
  transition: border-color 0.2s;
  cursor: pointer;
}
.omov-date-input:focus { border-color: var(--c-gold); }
.omov-date-sep { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-3); }
.omov-apply-btn:hover { background: var(--c-gold); color: #fff; border-color: var(--c-gold); }

.omov-refresh-btn svg { transition: transform 0.4s; }
.omov-refresh-btn.spinning svg { animation: omac-spin 0.6s linear infinite; }
@keyframes omac-spin { to { transform: rotate(360deg); } }

/* ── Section label ── */
.omov-section-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-3);
  margin: 22px 0 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.omov-section-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ── KPI Grid ── */


.omov-kpi {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
  min-width: 0;
}
.omov-kpi:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
.omov-kpi:active { transform: translateY(0) scale(0.98); }

.omov-kpi-bar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: var(--radius) var(--radius) 0 0;
}
.omov-kpi.gold  .omov-kpi-bar { background: var(--c-gold); }
.omov-kpi.blue  .omov-kpi-bar { background: var(--c-blue); }
.omov-kpi.green .omov-kpi-bar { background: var(--c-green); }
.omov-kpi.red   .omov-kpi-bar { background: var(--c-red); }
.omov-kpi.teal  .omov-kpi-bar { background: var(--c-teal); }
.omov-kpi.violet .omov-kpi-bar { background: var(--c-violet); }
.omov-kpi.amber .omov-kpi-bar { background: var(--c-amber); }

.omov-kpi-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.omov-kpi-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
  flex-shrink: 0;
}
.omov-kpi.gold  .omov-kpi-icon { background: var(--c-gold-bg);   color: var(--c-gold); }
.omov-kpi.blue  .omov-kpi-icon { background: var(--c-blue-bg);   color: var(--c-blue); }
.omov-kpi.green .omov-kpi-icon { background: var(--c-green-bg);  color: var(--c-green); }
.omov-kpi.red   .omov-kpi-icon { background: var(--c-red-bg);    color: var(--c-red); }
.omov-kpi.teal  .omov-kpi-icon { background: var(--c-teal-bg);   color: var(--c-teal); }
.omov-kpi.violet .omov-kpi-icon { background: var(--c-violet-bg); color: var(--c-violet); }
.omov-kpi.amber .omov-kpi-icon { background: var(--c-amber-bg);  color: var(--c-amber); }

.omov-kpi-val {
  font-family: 'Instrument Serif', serif;
  font-size: 26px;
  color: var(--text-1);
  line-height: 1.1;
  transition: all 0.4s;
}
.omov-kpi-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.omov-kpi-arrow {
  position: absolute;
  right: 10px;
  bottom: 10px;
  font-size: 12px;
  color: var(--text-3);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s, transform 0.2s;
}
.omov-kpi:hover .omov-kpi-arrow { opacity: 1; transform: translateX(0); }

/* ── Balance Cards ── */
.omov-balance-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 1100px) { .omov-balance-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 600px)  { .omov-balance-grid { grid-template-columns: 1fr; } }

.omov-bal-card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
}
.omov-bal-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-1px); }

.omov-bal-header {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 10px;
}
.omov-bal-icon {
  width: 30px;
  height: 30px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.omov-bal-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.omov-bal-val {
  font-family: 'Instrument Serif', serif;
  font-size: 22px;
  color: var(--text-1);
  margin-bottom: 8px;
}
.omov-bal-val.danger  { color: var(--c-red); }
.omov-bal-val.success { color: var(--c-green); }
.omov-bal-val.warning { color: var(--c-amber); }
.omov-bal-meta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  line-height: 1.6;
}
.omov-bal-acc-row {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  font-family: 'JetBrains Mono', monospace;
  padding: 2px 0;
}
.omov-bal-acc-name { color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 55%; }
.omov-bal-acc-amt  { color: var(--text-2); }

/* ── Payable Cards (Employee / Staff / Accounts) ── */
.omov-payable-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 900px) { .omov-payable-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 500px) { .omov-payable-grid { grid-template-columns: 1fr; } }

.omov-pay-card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
  position: relative;
  overflow: hidden;
}
.omov-pay-card::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
}
.omov-pay-card.emp-exp::before  { background: var(--c-amber); }
.omov-pay-card.staff-pay::before { background: var(--c-violet); }
.omov-pay-card.other::before    { background: var(--c-slate); }
.omov-pay-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-1px); }

.omov-pay-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
  margin-bottom: 8px;
}
.omov-pay-val {
  font-family: 'Instrument Serif', serif;
  font-size: 22px;
  color: var(--c-red);
  margin-bottom: 4px;
}
.omov-pay-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
}

/* ── Invoice Summary ── */
.omov-two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 0;
}
@media (max-width: 900px) { .omov-two-col { grid-template-columns: 1fr; } }

.omov-panel {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.omov-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 13px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--surface2);
}
.omov-panel-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-1);
  letter-spacing: -0.01em;
}
.omov-panel-link {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--c-blue);
  cursor: pointer;
  font-weight: 500;
  text-decoration: none;
  transition: opacity 0.2s;
}
.omov-panel-link:hover { opacity: 0.65; }
.omov-panel-body { padding: 6px 0; min-height: 120px; }

/* ── Invoice type bars ── */
.omov-type-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.15s;
}
.omov-type-row:last-child { border-bottom: none; }
.omov-type-row:hover { background: var(--surface2); }
.omov-type-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.omov-type-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
  min-width: 110px;
  flex-shrink: 0;
}
.omov-type-bar-wrap { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
.omov-type-bar { height: 100%; border-radius: 3px; transition: width 0.6s cubic-bezier(0.4,0,0.2,1); }
.omov-type-amount {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-2);
  min-width: 62px;
  text-align: right;
}
.omov-type-count {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  min-width: 36px;
  text-align: right;
}

/* ── Payment type bars ── */
.omov-pt-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.15s;
}
.omov-pt-row:last-child { border-bottom: none; }
.omov-pt-row:hover { background: var(--surface2); }
.omov-pt-name { font-size: 12px; font-weight: 600; color: var(--text-1); min-width: 90px; flex-shrink: 0; }
.omov-pt-bar-wrap { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
.omov-pt-bar { height: 100%; border-radius: 3px; transition: width 0.6s cubic-bezier(0.4,0,0.2,1); }
.omov-pt-amount { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-2); min-width: 62px; text-align: right; }
.omov-pt-count  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); min-width: 36px; text-align: right; }

/* ── Recent rows (sales / purchase) ── */
.omov-list-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.12s, padding-left 0.12s;
  border-radius: 4px;
}
.omov-list-row:last-child { border-bottom: none; }
.omov-list-row:hover { background: var(--surface2); padding-left: 20px; }
.omov-list-name {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--c-blue);
  font-weight: 500;
}
.omov-list-sub { font-size: 11px; color: var(--text-2); margin-top: 1px; }
.omov-list-right { text-align: right; flex-shrink: 0; margin-left: 12px; }
.omov-list-val { font-family: 'JetBrains Mono', monospace; font-size: 12px; color: var(--text-2); font-weight: 500; }

/* ── Invoice type badge ── */
.omov-inv-type-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  padding: 2px 6px;
  border-radius: 3px;
  background: var(--c-blue-bg);
  color: var(--c-blue);
  display: inline-block;
  margin-top: 2px;
}
.omov-pay-type-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  padding: 2px 6px;
  border-radius: 3px;
  display: inline-block;
  margin-top: 2px;
}
.pt-credit  { background: var(--c-blue-bg);   color: var(--c-blue); }
.pt-cash    { background: var(--c-green-bg);  color: var(--c-green); }
.pt-warranty { background: var(--c-amber-bg); color: var(--c-amber); }
.pt-insurance { background: var(--c-teal-bg); color: var(--c-teal); }

/* ── Overdue table ── */
.omov-overdue-row {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  gap: 10px;
  cursor: pointer;
  transition: background 0.15s;
}
.omov-overdue-row:last-child { border-bottom: none; }
.omov-overdue-row:hover { background: var(--surface2); }
.omov-overdue-name { font-size: 12px; font-weight: 600; color: var(--text-1); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omov-overdue-sub  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); }
.omov-overdue-amt  { font-family: 'JetBrains Mono', monospace; font-size: 12px; font-weight: 600; color: var(--c-red); flex-shrink: 0; }
.omov-overdue-due  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); flex-shrink: 0; min-width: 76px; text-align: right; }

/* ── Loader ── */
.omov-loader {
  text-align: center;
  padding: 32px;
  color: var(--text-3);
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
}

.omov-pulse { animation: omac-pulse-anim 1.4s ease-in-out infinite; }
@keyframes omac-pulse-anim { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }

/* ── Show more ── */
.omov-show-more {
  text-align: center;
  padding: 9px 16px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--c-blue);
  cursor: pointer;
  border-top: 1px solid var(--border);
  transition: background 0.15s;
  user-select: none;
}
.omov-show-more:hover { background: var(--surface2); }

/* ── Modal ── */
.omov-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(28,26,22,0.5);
  backdrop-filter: blur(4px);
  z-index: 9999;
  align-items: flex-start;
  justify-content: center;
  overflow-y: auto;
}
.omov-modal-overlay.active { display: flex; animation: omac-fade 0.18s ease; }
@keyframes omac-fade { from { opacity: 0; } to { opacity: 1; } }

.omov-modal-box {
  background: var(--surface);
  border: 1px solid var(--border-md);
  border-radius: var(--radius);
  width: 620px;
  max-width: 96vw;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 64px rgba(28,26,22,0.25);
  animation: omac-slide 0.22s cubic-bezier(0.4,0,0.2,1);
  flex-shrink: 0;
}
@keyframes omac-slide { from { transform: translateY(16px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

.omov-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--surface2);
  border-radius: var(--radius) var(--radius) 0 0;
  flex-shrink: 0;
}
.omov-modal-title {
  font-family: 'Instrument Serif', serif;
  font-size: 16px;
  color: var(--text-1);
}
.omov-modal-subtitle {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  margin-top: 3px;
}
.omov-modal-close {
  background: none;
  border: none;
  color: var(--text-3);
  font-size: 16px;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition: all 0.15s;
  flex-shrink: 0;
  margin-left: 12px;
}
.omov-modal-close:hover { background: var(--border); color: var(--text-1); }
.omov-modal-body { padding: 18px 0 0; overflow-y: auto; flex: 1; min-height: 0; }
.omov-modal-body .omov-detail-grid { margin: 0 20px 14px; }
.omov-modal-body .omov-section-divider { margin: 12px 20px 8px; font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.06em; padding-bottom: 6px; border-bottom: 1px solid var(--border); }
.omov-modal-body .omov-list-row { padding: 9px 20px; }
.omov-modal-body .omov-loader { padding: 20px; }
.omov-modal-body .omov-search-input { margin: 0 20px 10px; width: calc(100% - 40px); }
.omov-modal-footer { padding: 14px 20px; border-top: 1px solid var(--border); background: var(--surface2); border-radius: 0 0 var(--radius) var(--radius); flex-shrink: 0; }

.omov-detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 14px; }
.omov-detail-block { background: var(--surface2); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 10px 12px; }
.omov-detail-block-label { font-family: 'JetBrains Mono', monospace; font-size: 9px; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px; }
.omov-detail-block-val { font-size: 13px; font-weight: 600; color: var(--text-1); }

.omov-cost-bar-row { margin-bottom: 10px; }
.omov-cost-bar-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--text-2); margin-bottom: 5px; }
.omov-cost-bar-label span:last-child { font-family: 'JetBrains Mono', monospace; color: var(--text-1); font-weight: 500; }
.omov-cost-bar-track { height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; }
.omov-cost-bar-fill { height: 100%; border-radius: 3px; transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }

.omov-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--c-blue-bg);
  border: 1px solid var(--c-blue);
  color: var(--c-blue);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.18s;
}
.omov-open-btn:hover { background: var(--c-blue); color: #fff; }

.omov-search-input {
  width: 100%;
  padding: 8px 12px;
  margin-bottom: 10px;
  background: var(--surface2);
  border: 1px solid var(--border-md);
  border-radius: 8px;
  color: var(--text-1);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  outline: none;
  transition: border-color 0.2s;
  box-sizing: border-box;
}
.omov-search-input:focus { border-color: var(--c-gold); }
.omov-search-input::placeholder { color: var(--text-3); }

.omov-chart-panel {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px 18px;
}

.omov-chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  flex-wrap: wrap;
  gap: 10px;
}

.omov-chart-legend {
  display: flex;
  align-items: center;
  gap: 6px;
}

.omov-legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.omov-legend-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-2);
}

.omov-chart-totals {
  display: flex;
  gap: 18px;
}

.omov-chart-total-item {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.omov-chart-total-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.omov-chart-total-val {
  font-family: 'Instrument Serif', serif;
  font-size: 16px;
  line-height: 1.2;
}

.omov-chart-total-val.green { color: var(--c-green); }
.omov-chart-total-val.amber { color: var(--c-amber); }

.omov-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 1100px) { .omov-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px)  { .omov-kpi-grid { grid-template-columns: 1fr; } }

.omov-chart-date-filter {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.omov-chart-apply-btn {
  font-size: 11px;
  padding: 5px 10px;
  border-radius: 6px;
}

.omov-chart-apply-btn:hover {
  background: var(--c-gold);
  color: #fff;
  border-color: var(--c-gold);
}

.omov-chart-reset-btn {
  font-size: 13px;
  padding: 4px 9px;
  border-radius: 6px;
  min-width: 30px;
  justify-content: center;
}

.omov-chart-reset-btn:hover {
  background: var(--c-red-bg);
  color: var(--c-red);
  border-color: var(--c-red);
}

.omov-chart-clicked-info {
  display: none;
  align-items: flex-start;
  gap: 16px;
  background: var(--surface2);
  border: 1px solid var(--border-md);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  margin-bottom: 12px;
  flex-wrap: wrap;
  position: relative;
  animation: omac-fade 0.15s ease;
}

.omov-chart-info-month {
  font-family: 'Instrument Serif', serif;
  font-size: 15px;
  color: var(--text-1);
  font-weight: 400;
  min-width: 80px;
  align-self: center;
}

.omov-chart-info-row {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 130px;
}

.omov-chart-info-dot {
  width: 8px;
  height: 8px;
  border-radius: 3px;
  flex-shrink: 0;
}

.omov-chart-info-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  min-width: 55px;
}

.omov-chart-info-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
}

.omov-chart-info-val.green { color: var(--c-green); }
.omov-chart-info-val.amber { color: var(--c-amber); }

.omov-chart-info-divider {
  width: 1px;
  height: 36px;
  background: var(--border);
  align-self: center;
}

.omov-chart-info-close {
  position: absolute;
  top: 8px;
  right: 10px;
  background: none;
  border: none;
  color: var(--text-3);
  cursor: pointer;
  font-size: 13px;
  padding: 2px 5px;
  border-radius: 4px;
  transition: all 0.15s;
  line-height: 1;
}

.omov-chart-info-close:hover {
  background: var(--border);
  color: var(--text-1);
}

.omov-chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  flex-wrap: wrap;
  gap: 10px;
}

script:
(function init() {
  if (!root_element || !root_element.querySelector) { setTimeout(init, 100); return; }

  var root = root_element;
  var THEME_KEY = 'omeir_dash_theme';
  var currentDays = 5;
  var allJobs = [];
  var allTechs = [];
  var dashData = {};
  var pieChart, ageChart, techDonut;
  var chartsReady = false;

  var q  = function (sel) { return root.querySelector(sel); };
  var qa = function (sel) { return root.querySelectorAll(sel); };

  var setText = function (id, val) {
    var el = q('#' + id);
    if (el) el.textContent = (val !== null && val !== undefined) ? val : '—';
  };

  var fmt = function (val) {
    if (val === null || val === undefined) return '—';
    var num = parseFloat(val) || 0;
    if (Math.abs(num) >= 1000000) return (num / 1000000).toFixed(2) + 'M';
    if (Math.abs(num) >= 1000)    return (num / 1000).toFixed(1) + 'K';
    return num.toLocaleString('en-AE', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
  };

  var getInitials = function (name) {
    if (!name) return '??';
    return name.split(' ').map(function (w) { return w[0] || ''; }).join('').substring(0, 2).toUpperCase();
  };

  var avColors = ['av-blue', 'av-teal', 'av-amber'];
  var avColor  = function (idx) { return avColors[idx % avColors.length]; };
  var ageCls   = function (d) { return d >= 20 ? 'age-crit' : d >= 10 ? 'age-warn' : 'age-ok'; };

  var getDashRoot = function () { return q('#omeirDashboard') || root; };

  var applyTheme = function (theme) {
    if (theme === 'light') getDashRoot().classList.add('light-theme');
    else getDashRoot().classList.remove('light-theme');
  };

  var toggleTheme = function () {
    var isLight = getDashRoot().classList.contains('light-theme');
    var next = isLight ? 'dark' : 'light';
    applyTheme(next);
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  };

  var loadTheme = function () {
    try {
      var saved = localStorage.getItem(THEME_KEY);
      if (saved) { applyTheme(saved); return; }
    } catch (e) {}
    applyTheme('dark');
  };

  var setDate = function () {
    var el = q('#omDate');
    if (el) el.textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
  };

  var setLoading = function (on) {
    ['om-kpi-total', 'om-kpi-age', 'om-kpi-active', 'om-kpi-idle', 'om-kpi-value',
     'om-kpi-total-jo', 'om-kpi-pending-jo', 'om-kpi-draft-jo', 'om-kpi-multi-jo', 'om-kpi-gate-jo'].forEach(function (id) {
      var el = q('#' + id);
      if (!el) return;
      if (on) { el.textContent = '…'; el.classList.add('om-pulse'); }
      else el.classList.remove('om-pulse');
    });
    if (on) {
      var wip = q('#om-wip-wrap');
      var tl  = q('#om-tech-list');
      if (wip) wip.innerHTML = '<div class="om-loader">Loading...</div>';
      if (tl)  tl.innerHTML  = '<div class="om-loader">Loading...</div>';
    }
  };

  var openModal = function (title, subtitle, bodyHtml) {
    setText('om-modal-title', title);
    setText('om-modal-subtitle', subtitle || '');
    var body = q('#om-modal-body');
    if (body) body.innerHTML = bodyHtml;
    var modal = q('#omModal');
    if (modal) modal.classList.add('active');
  };

  var closeModal = function () {
    var modal = q('#omModal');
    if (modal) modal.classList.remove('active');
  };

  var showJobModal = function (job) {
    var totVal = (parseFloat(job.labour) || 0) + (parseFloat(job.parts) || 0) + (parseFloat(job.sublet) || 0);
    var pct = function (v) { return totVal ? Math.round((parseFloat(v) || 0) / totVal * 100) : 0; };
    var bars = [
      { label: 'Labour', val: job.labour || 0, color: '#3b82f6', pct: pct(job.labour) },
      { label: 'Parts',  val: job.parts  || 0, color: '#14b8a6', pct: pct(job.parts) },
      { label: 'Sublet', val: job.sublet || 0, color: '#f59e0b', pct: pct(job.sublet) }
    ];
    var barsHtml = bars.map(function (b) {
      return '<div class="om-cost-bar-row">' +
        '<div class="om-cost-bar-label"><span>' + b.label + '</span><span>' + fmt(b.val) + ' (' + b.pct + '%)</span></div>' +
        '<div class="om-cost-bar-track"><div class="om-cost-bar-fill" style="width:' + b.pct + '%;background:' + b.color + '"></div></div>' +
      '</div>';
    }).join('');
    var body =
      '<div class="om-detail-grid">' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Customer</div><div class="om-detail-block-val">' + (job.customer || '—') + '</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Vehicle</div><div class="om-detail-block-val">' + (job.make || '') + ' ' + (job.model || '') + '</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Plate / VIN</div><div class="om-detail-block-val mono">' + (job.vehicle || '—') + '</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Job Type</div><div class="om-detail-block-val">' + (job.job_type || '—') + '</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Age</div><div class="om-detail-block-val"><span class="om-age-badge ' + ageCls(job.age_days) + '">' + job.age_days + ' days</span></div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Total Value</div><div class="om-detail-block-val" style="color:var(--accent-teal)">' + fmt(totVal) + '</div></div>' +
      '</div>' +
      '<div class="om-section-label">Cost Breakdown</div>' +
      barsHtml +
      '<button class="om-open-btn" id="modal-open-job">Open Job Order ↗</button>';
    openModal(job.name, (job.make || '') + ' ' + (job.model || '') + ' · ' + (job.customer || ''), body);
    setTimeout(function () {
      var btn = q('#modal-open-job');
      if (btn) btn.addEventListener('click', function () { closeModal(); frappe.set_route('Form', 'Job Order', job.name); });
    }, 50);
  };

  var showWipListModal = function (jobs, title, subtitle) {
    if (!jobs.length) { openModal(title, subtitle, '<div class="om-loader">No jobs in this group</div>'); return; }
    var rows = jobs.map(function (j) {
      var totV = (parseFloat(j.labour) || 0) + (parseFloat(j.parts) || 0) + (parseFloat(j.sublet) || 0);
      return '<div class="om-modal-list-row" data-name="' + j.name + '">' +
        '<div>' +
          '<div class="om-modal-list-name">' + j.name + '</div>' +
          '<div class="om-modal-list-sub">' + (j.customer || '—') + ' · ' + (j.make || '') + ' ' + (j.model || '') + '</div>' +
        '</div>' +
        '<div class="om-modal-list-right">' +
          '<div class="om-val-cell">' + fmt(totV) + '</div>' +
          '<div style="margin-top:4px"><span class="om-age-badge ' + ageCls(j.age_days) + '">' + j.age_days + 'd</span></div>' +
        '</div>' +
      '</div>';
    }).join('');
    openModal(title, subtitle, rows);
    setTimeout(function () {
      q('#om-modal-body').querySelectorAll('.om-modal-list-row').forEach(function (row) {
        row.addEventListener('click', function () {
          var job = allJobs.filter(function (j) { return j.name === row.dataset.name; })[0];
          if (job) showJobModal(job);
        });
      });
    }, 50);
  };

  var showSimpleListModal = function (items, title, subtitle, fields) {
    if (!items || !items.length) { openModal(title, subtitle, '<div class="om-loader">No records found</div>'); return; }
    var rows = items.map(function (item) {
      return '<div class="om-modal-list-row" data-name="' + (item.name || '') + '">' +
        '<div>' +
          '<div class="om-modal-list-name">' + (item.name || '—') + '</div>' +
          '<div class="om-modal-list-sub">' + (item.customer || '—') + ' · ' + (item.make || '') + ' ' + (item.model || '') + '</div>' +
        '</div>' +
        '<div class="om-modal-list-right">' +
          (fields && fields.badge ? '<span class="om-type-badge">' + (item[fields.badge] || '') + '</span>' : '') +
          (fields && fields.val   ? '<div class="om-val-cell" style="margin-top:4px">' + (item[fields.val] || '') + '</div>' : '') +
        '</div>' +
      '</div>';
    }).join('');
    openModal(title, subtitle, rows);
    setTimeout(function () {
      q('#om-modal-body').querySelectorAll('.om-modal-list-row').forEach(function (row) {
        row.addEventListener('click', function () {
          closeModal();
          frappe.set_route('Form', 'Job Order', row.dataset.name);
        });
      });
    }, 50);
  };

  var showCostBreakdownModal = function () {
    var filtered = allJobs.filter(function (j) { return j.age_days >= currentDays; });
    var totL = filtered.reduce(function (s, j) { return s + (parseFloat(j.labour) || 0); }, 0);
    var totP = filtered.reduce(function (s, j) { return s + (parseFloat(j.parts)  || 0); }, 0);
    var totS = filtered.reduce(function (s, j) { return s + (parseFloat(j.sublet) || 0); }, 0);
    var totV = totL + totP + totS;
    var pct  = function (v) { return totV ? Math.round(v / totV * 100) : 0; };
    var topByLabour = filtered.slice().sort(function (a, b) { return (b.labour || 0) - (a.labour || 0); }).slice(0, 5);
    var topByParts  = filtered.slice().sort(function (a, b) { return (b.parts  || 0) - (a.parts  || 0); }).slice(0, 5);
    var makeTopRows = function (list, field, color) {
      return list.map(function (j) {
        return '<div class="om-modal-list-row" data-name="' + j.name + '">' +
          '<div><div class="om-modal-list-name">' + j.name + '</div><div class="om-modal-list-sub">' + (j.customer || '—') + '</div></div>' +
          '<div class="om-val-cell" style="color:' + color + '">' + fmt(j[field]) + '</div>' +
        '</div>';
      }).join('');
    };
    var body =
      '<div class="om-section-label">Summary</div>' +
      '<div class="om-detail-grid" style="margin-bottom:18px">' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Labour</div><div class="om-detail-block-val" style="color:#3b82f6">' + fmt(totL) + '</div><div class="om-kpi-sub">' + pct(totL) + '% of total</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Parts</div><div class="om-detail-block-val" style="color:#14b8a6">' + fmt(totP) + '</div><div class="om-kpi-sub">' + pct(totP) + '% of total</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Sublet</div><div class="om-detail-block-val" style="color:#f59e0b">' + fmt(totS) + '</div><div class="om-kpi-sub">' + pct(totS) + '% of total</div></div>' +
        '<div class="om-detail-block"><div class="om-detail-block-label">Grand Total</div><div class="om-detail-block-val" style="color:var(--accent-teal)">' + fmt(totV) + '</div><div class="om-kpi-sub">' + filtered.length + ' jobs</div></div>' +
      '</div>' +
      '<div class="om-section-label">Top 5 by Labour Cost</div>' + makeTopRows(topByLabour, 'labour', '#3b82f6') +
      '<div class="om-section-label" style="margin-top:16px">Top 5 by Parts Cost</div>' + makeTopRows(topByParts, 'parts', '#14b8a6');
    openModal('Cost Breakdown', filtered.length + ' WIP jobs · ' + currentDays + '+ days', body);
    setTimeout(function () {
      q('#om-modal-body').querySelectorAll('.om-modal-list-row').forEach(function (row) {
        row.addEventListener('click', function () {
          var job = allJobs.filter(function (j) { return j.name === row.dataset.name; })[0];
          if (job) showJobModal(job);
        });
      });
    }, 50);
  };

  var showTechModal = function (tech, idx) {
    var avCls    = tech.status === 'Active' ? avColor(idx) : 'av-gray';
    var sCls     = tech.status === 'Active' ? 's-active' : 's-idle';
    var initials = getInitials(tech.employee_name || tech.employee);
    var jobsForTech = allJobs.filter(function (j) { return j.assigned_employee && j.assigned_employee === tech.employee; });
    var jobsHtml = jobsForTech.length
      ? jobsForTech.map(function (j) {
          return '<div class="om-modal-list-row" data-name="' + j.name + '">' +
            '<div><div class="om-modal-list-name">' + j.name + '</div><div class="om-modal-list-sub">' + (j.customer || '—') + ' · ' + (j.make || '') + ' ' + (j.model || '') + '</div></div>' +
            '<span class="om-age-badge ' + ageCls(j.age_days) + '">' + j.age_days + 'd</span>' +
          '</div>';
        }).join('')
      : '<div class="om-loader" style="padding:16px">No jobs linked to this technician</div>';
    var body =
      '<div class="om-tech-detail-header">' +
        '<div class="om-avatar-lg ' + avCls + '">' + initials + '</div>' +
        '<div>' +
          '<div class="om-tech-detail-name">' + (tech.employee_name || tech.employee) + '</div>' +
          '<div class="om-tech-detail-sub">' + tech.employee + ' · <span class="om-status-badge ' + sCls + '">' + tech.status + '</span></div>' +
        '</div>' +
      '</div>' +
      '<div class="om-section-label">Current Assignment</div>' +
      '<div class="om-detail-block" style="margin-bottom:16px"><div class="om-detail-block-label">Job / Task</div><div class="om-detail-block-val">' + (tech.current_job || 'No active assignment') + '</div></div>' +
      '<div class="om-section-label">Linked WIP Jobs</div>' + jobsHtml +
      '<button class="om-open-btn" id="modal-open-emp" style="margin-top:10px">Open Employee Record ↗</button>';
    openModal(tech.employee_name || tech.employee, tech.status + ' · ' + (tech.current_job ? 'On job' : 'Available'), body);
    setTimeout(function () {
      var btn = q('#modal-open-emp');
      if (btn) btn.addEventListener('click', function () { closeModal(); frappe.set_route('Form', 'Employee', tech.employee); });
      q('#om-modal-body').querySelectorAll('.om-modal-list-row').forEach(function (row) {
        row.addEventListener('click', function () {
          var job = allJobs.filter(function (j) { return j.name === row.dataset.name; })[0];
          if (job) showJobModal(job);
        });
      });
    }, 50);
  };

  var showTechGroupModal = function (filterStatus) {
    var list = filterStatus ? allTechs.filter(function (t) { return t.status === filterStatus; }) : allTechs;
    var title = filterStatus ? filterStatus + ' Technicians' : 'All Technicians';
    if (!list.length) { openModal(title, '', '<div class="om-loader">No technicians found</div>'); return; }
    var rows = list.map(function (t, idx) {
      var avCls    = t.status === 'Active' ? avColor(idx) : 'av-gray';
      var sCls     = t.status === 'Active' ? 's-active' : 's-idle';
      var initials = getInitials(t.employee_name || t.employee);
      return '<div class="om-modal-list-row" data-idx="' + allTechs.indexOf(t) + '">' +
        '<div style="display:flex;align-items:center;gap:10px">' +
          '<div class="om-avatar ' + avCls + '">' + initials + '</div>' +
          '<div>' +
            '<div class="om-modal-list-name">' + (t.employee_name || t.employee) + '</div>' +
            '<div class="om-modal-list-sub">' + (t.current_job || 'No assignment') + '</div>' +
          '</div>' +
        '</div>' +
        '<span class="om-status-badge ' + sCls + '">' + t.status + '</span>' +
      '</div>';
    }).join('');
    openModal(title, list.length + ' technician' + (list.length !== 1 ? 's' : ''), rows);
    setTimeout(function () {
      q('#om-modal-body').querySelectorAll('.om-modal-list-row').forEach(function (row) {
        row.addEventListener('click', function () {
          var idx  = parseInt(row.dataset.idx, 10);
          var tech = allTechs[idx];
          if (tech) showTechModal(tech, idx);
        });
      });
    }, 50);
  };

  var showAgeBucketModal = function (bucketLabel, minDay, maxDay) {
    var jobs = allJobs.filter(function (j) {
      return j.age_days >= minDay && (maxDay === null || j.age_days < maxDay);
    });
    showWipListModal(jobs, 'Jobs: ' + bucketLabel, jobs.length + ' job' + (jobs.length !== 1 ? 's' : ''));
  };

  var buildCharts = function () {
    if (chartsReady) return;
    if (typeof Chart === 'undefined') return;
    pieChart = new Chart(q('#om-pie-chart'), {
      type: 'doughnut',
      data: {
        labels: ['Labour', 'Parts', 'Sublet'],
        datasets: [{ data: [0, 0, 0], backgroundColor: ['#3b82f6', '#14b8a6', '#f59e0b'], borderWidth: 0, hoverOffset: 8 }]
      },
      options: {
        responsive: true, maintainAspectRatio: false, cutout: '62%',
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: function (ctx) {
            var tot = ctx.dataset.data.reduce(function (a, b) { return a + b; }, 0);
            var pct = tot ? Math.round(ctx.parsed / tot * 100) : 0;
            return ' ' + ctx.label + ': ' + fmt(ctx.parsed) + ' (' + pct + '%)';
          }}}
        },
        onClick: function () { showCostBreakdownModal(); }
      }
    });
    ageChart = new Chart(q('#om-age-chart'), {
      type: 'bar',
      data: {
        labels: ['< 10 days', '10–20 days', '20+ days'],
        datasets: [{ data: [0, 0, 0], backgroundColor: ['#22c55e', '#f59e0b', '#ef4444'], borderWidth: 0, borderRadius: 5 }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (ctx) {
          return ' ' + ctx.parsed.y + ' job' + (ctx.parsed.y !== 1 ? 's' : '');
        }}}},
        scales: {
          x: { grid: { display: false }, ticks: { color: '#454d66', font: { size: 11 } } },
          y: { beginAtZero: true, ticks: { stepSize: 1, color: '#454d66', font: { size: 11 } }, grid: { color: 'rgba(255,255,255,0.04)' } }
        },
        onClick: function (evt, elements) {
          if (!elements.length) return;
          var idx = elements[0].index;
          var buckets = [
            { label: '< 10 days',  min: 0,  max: 10   },
            { label: '10–20 days', min: 10, max: 20   },
            { label: '20+ days',   min: 20, max: null  }
          ];
          var b = buckets[idx];
          if (b) showAgeBucketModal(b.label, b.min, b.max);
        }
      }
    });
    techDonut = new Chart(q('#om-tech-donut'), {
      type: 'doughnut',
      data: {
        labels: ['Active', 'Idle'],
        datasets: [{ data: [0, 0], backgroundColor: ['#22c55e', '#454d66'], borderWidth: 0, hoverOffset: 8 }]
      },
      options: {
        responsive: true, maintainAspectRatio: false, cutout: '65%',
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: function (ctx) { return ' ' + ctx.label + ': ' + ctx.parsed; }}}
        },
        onClick: function (evt, elements) {
          if (!elements.length) { showTechGroupModal(null); return; }
          var idx    = elements[0].index;
          var status = idx === 0 ? 'Active' : 'Idle';
          showTechGroupModal(status);
        }
      }
    });
    chartsReady = true;
  };

  var render = function () {
    var filtered = allJobs.filter(function (j) { return (j.age_days || 0) >= currentDays; });
    var totL = filtered.reduce(function (s, j) { return s + (parseFloat(j.labour) || 0); }, 0);
    var totP = filtered.reduce(function (s, j) { return s + (parseFloat(j.parts)  || 0); }, 0);
    var totS = filtered.reduce(function (s, j) { return s + (parseFloat(j.sublet) || 0); }, 0);
    var totV = totL + totP + totS;
    var active = allTechs.filter(function (t) { return t.status === 'Active'; }).length;
    var idle   = allTechs.filter(function (t) { return t.status === 'Idle';   }).length;
    var avgAge = filtered.length
      ? Math.round(filtered.reduce(function (s, j) { return s + (j.age_days || 0); }, 0) / filtered.length) : 0;

    setText('om-kpi-total',     filtered.length);
    setText('om-kpi-total-sub', filtered.length + ' jobs above ' + currentDays + 'd');
    setText('om-kpi-age',       avgAge);
    setText('om-kpi-active',    active);
    setText('om-kpi-idle',      idle);
    setText('om-kpi-value',     fmt(totV));
    setText('om-ts-active',     active);
    setText('om-ts-idle',       idle);
    setText('om-ts-total',      allTechs.length);

    setText('om-kpi-total-jo',   dashData.total_job_cards   || 0);
    setText('om-kpi-pending-jo', dashData.pending_job_cards || 0);
    setText('om-kpi-draft-jo',   dashData.draft_job_cards   || 0);
    setText('om-kpi-multi-jo',   dashData.multi_invoice_count || 0);
    setText('om-kpi-gate-jo',    dashData.gate_pass_count   || 0);

    var pct = function (v) { return totV ? Math.round(v / totV * 100) : 0; };
    var legend = q('#om-pie-legend');
    if (legend) {
      legend.innerHTML =
        '<span class="om-legend-item"><span class="om-lsq" style="background:#3b82f6"></span>Labour ' + pct(totL) + '%</span>' +
        '<span class="om-legend-item"><span class="om-lsq" style="background:#14b8a6"></span>Parts '  + pct(totP) + '%</span>' +
        '<span class="om-legend-item"><span class="om-lsq" style="background:#f59e0b"></span>Sublet ' + pct(totS) + '%</span>';
    }

    if (chartsReady) {
      var b1 = filtered.filter(function (j) { return j.age_days < 10; }).length;
      var b2 = filtered.filter(function (j) { return j.age_days >= 10 && j.age_days < 20; }).length;
      var b3 = filtered.filter(function (j) { return j.age_days >= 20; }).length;
      pieChart.data.datasets[0].data  = [totL, totP, totS]; pieChart.update();
      ageChart.data.datasets[0].data  = [b1, b2, b3];       ageChart.update();
      techDonut.data.datasets[0].data = [active, idle];      techDonut.update();
    }

    var LIMIT = 20;

    var wipWrap = q('#om-wip-wrap');
    var wipMore = q('#om-wip-viewmore');
    var wipMoreBtn = q('#om-wip-viewmore-btn');
    var wipTotalCount = q('#om-wip-total-count');
    var wipCount = q('#om-wip-count');

    if (wipCount) wipCount.textContent = 'Showing ' + Math.min(filtered.length, LIMIT) + ' of ' + filtered.length;

    if (wipWrap) {
      if (!filtered.length) {
        wipWrap.innerHTML = '<div class="om-loader">No WIP jobs found above ' + currentDays + ' days</div>';
        if (wipMore) wipMore.style.display = 'none';
      } else {
        var shown = filtered.slice(0, LIMIT);
        var rows = shown.map(function (j) {
          var totJV = (parseFloat(j.labour) || 0) + (parseFloat(j.parts) || 0) + (parseFloat(j.sublet) || 0);
          return '<tr class="om-job-row" data-name="' + (j.name || '') + '">' +
            '<td><span class="om-job-link">' + (j.name || '—') + '</span></td>' +
            '<td><span class="om-vehicle-name">' + (j.make || '') + ' ' + (j.model || '') + '</span>' +
                '<span class="om-vehicle-plate">' + (j.vehicle || '') + '</span></td>' +
            '<td style="color:var(--text-secondary);font-size:12px;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + (j.customer || '—') + '</td>' +
            '<td><span class="om-age-badge ' + ageCls(j.age_days) + '">' + j.age_days + 'd</span></td>' +
            '<td><span class="om-type-badge">' + (j.job_type || 'WIP') + '</span></td>' +
            '<td class="om-val-cell">' + fmt(totJV) + '</td>' +
          '</tr>';
        }).join('');
        wipWrap.innerHTML =
          '<div class="om-table-wrap">' +
          '<table class="om-table"><thead><tr>' +
          '<th>Job #</th><th>Vehicle</th><th>Customer</th><th>Age</th><th>Type</th><th>Value</th>' +
          '</tr></thead><tbody>' + rows + '</tbody></table></div>';
        wipWrap.querySelectorAll('.om-job-row').forEach(function (row) {
          row.addEventListener('click', function () {
            var job = allJobs.filter(function (j) { return j.name === row.dataset.name; })[0];
            if (job) showJobModal(job);
          });
        });
        if (filtered.length > LIMIT) {
          if (wipMore) wipMore.style.display = 'block';
          if (wipTotalCount) wipTotalCount.textContent = filtered.length;
          if (wipMoreBtn) {
            wipMoreBtn.onclick = function () {
              showWipListModal(filtered, 'All WIP Job Cards', filtered.length + ' jobs · ' + currentDays + '+ days');
            };
          }
        } else {
          if (wipMore) wipMore.style.display = 'none';
        }
      }
    }

    var techList  = q('#om-tech-list');
    var techMore  = q('#om-tech-viewmore');
    var techMoreBtn = q('#om-tech-viewmore-btn');
    var techTotalCount = q('#om-tech-total-count');
    var techCount = q('#om-tech-count');

    if (techCount) techCount.textContent = 'Showing ' + Math.min(allTechs.length, LIMIT) + ' of ' + allTechs.length;

    if (techList) {
      if (!allTechs.length) {
        techList.innerHTML = '<div class="om-loader">No technicians found</div>';
        if (techMore) techMore.style.display = 'none';
      } else {
        var shownTechs = allTechs.slice(0, LIMIT);
        techList.innerHTML = shownTechs.map(function (t, idx) {
          var avCls    = t.status === 'Active' ? avColor(idx) : 'av-gray';
          var sCls     = t.status === 'Active' ? 's-active' : 's-idle';
          var initials = getInitials(t.employee_name || t.employee);
          return '<div class="om-tech-row" data-idx="' + idx + '">' +
            '<div class="om-avatar ' + avCls + '">' + initials + '</div>' +
            '<div class="om-tech-info">' +
              '<div class="om-tech-name">' + (t.employee_name || t.employee || '—') + '</div>' +
              '<div class="om-tech-job">'  + (t.current_job || 'No assignment') + '</div>' +
            '</div>' +
            '<span class="om-status-badge ' + sCls + '">' + (t.status || '—') + '</span>' +
          '</div>';
        }).join('');
        techList.querySelectorAll('.om-tech-row').forEach(function (row) {
          row.addEventListener('click', function () {
            var idx  = parseInt(row.dataset.idx, 10);
            var tech = allTechs[idx];
            if (tech) showTechModal(tech, idx);
          });
        });
        if (allTechs.length > LIMIT) {
          if (techMore) techMore.style.display = 'block';
          if (techTotalCount) techTotalCount.textContent = allTechs.length;
          if (techMoreBtn) {
            techMoreBtn.onclick = function () { showTechGroupModal(null); };
          }
        } else {
          if (techMore) techMore.style.display = 'none';
        }
      }
    }
  };

  var loadChartJS = function (cb) {
    if (typeof Chart !== 'undefined') { cb(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js';
    s.onload = cb;
    document.head.appendChild(s);
  };

  var forceChartResize = function () {
    if (!chartsReady) return;
    [pieChart, ageChart, techDonut].forEach(function (c) { if (c) { c.resize(); c.update(); } });
  };

  var isFirstLoad = true;

  var refresh = function () {
    var btn = q('#omRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);
    frappe.call({
      method: 'omeir_motors.omeir_motors.api.dashboard.get_workshop_dashboard_data',
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load workshop data.', indicator: 'red' });
          setLoading(false);
          return;
        }
        dashData = r.message;
        allJobs  = r.message.jobs        || [];
        allTechs = r.message.technicians || [];
        setLoading(false);
        loadChartJS(function () {
          buildCharts();
          render();
          if (isFirstLoad) {
            isFirstLoad = false;
            requestAnimationFrame(function () {
              requestAnimationFrame(function () { forceChartResize(); });
            });
            setTimeout(forceChartResize, 500);
          }
        });
      }
    });
  };

  var attachEvents = function () {
    var btn = q('#omRefreshBtn');
    if (btn) btn.addEventListener('click', refresh);

    var themeBtn = q('#omThemeBtn');
    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

    var overlay = q('#omModal');
    if (overlay) overlay.addEventListener('click', function (e) { if (e.target === overlay) closeModal(); });
    var closeBtn = q('#om-modal-close-btn');
    if (closeBtn) closeBtn.addEventListener('click', closeModal);

    qa('.om-pill').forEach(function (pill) {
      pill.addEventListener('click', function () {
        qa('.om-pill').forEach(function (p) { p.classList.remove('active'); });
        this.classList.add('active');
        currentDays = parseInt(this.dataset.days, 10);
        render();
      });
    });

    var kpiWip = q('#kpi-card-wip');
    if (kpiWip) kpiWip.addEventListener('click', function () {
      var filtered = allJobs.filter(function (j) { return j.age_days >= currentDays; });
      showWipListModal(filtered, 'WIP Job Cards', filtered.length + ' jobs · ' + currentDays + '+ days');
    });

    var kpiAge = q('#kpi-card-age');
    if (kpiAge) kpiAge.addEventListener('click', function () {
      var sorted = allJobs.filter(function (j) { return j.age_days >= currentDays; })
        .slice().sort(function (a, b) { return b.age_days - a.age_days; });
      showWipListModal(sorted, 'Jobs by Age', 'Oldest first · ' + currentDays + '+ days');
    });

    var kpiActive = q('#kpi-card-active');
    if (kpiActive) kpiActive.addEventListener('click', function () { showTechGroupModal('Active'); });

    var kpiIdle = q('#kpi-card-idle');
    if (kpiIdle) kpiIdle.addEventListener('click', function () { showTechGroupModal('Idle'); });

    var kpiValue = q('#kpi-card-value');
    if (kpiValue) kpiValue.addEventListener('click', function () { showCostBreakdownModal(); });

    var kpiTotal = q('#kpi-card-total');
    if (kpiTotal) kpiTotal.addEventListener('click', function () {
      frappe.set_route('List', 'Job Order', { docstatus: 1 });
    });

    var kpiPending = q('#kpi-card-pending');
    if (kpiPending) kpiPending.addEventListener('click', function () {
      showWipListModal(allJobs, 'Pending Job Cards', allJobs.length + ' pending jobs');
    });

    var kpiDraft = q('#kpi-card-draft');
    if (kpiDraft) kpiDraft.addEventListener('click', function () {
      frappe.set_route('List', 'Job Order', { docstatus: 0 });
    });

    var kpiMulti = q('#kpi-card-multi');
    if (kpiMulti) kpiMulti.addEventListener('click', function () {
      var items = dashData.multi_invoice_jobs || [];
      showSimpleListModal(items, 'Multi-Invoice Job Orders', items.length + ' job orders with 2+ invoices', { badge: 'invoice_count', val: 'status' });
    });

    var kpiGate = q('#kpi-card-gate');
    if (kpiGate) kpiGate.addEventListener('click', function () {
      var items = dashData.gate_pass_jobs || [];
      showSimpleListModal(items, 'Gate Pass Issued', items.length + ' vehicles released', { val: 'status' });
    });

    var pieCard = q('#chart-card-pie');
    if (pieCard) pieCard.addEventListener('click', function (e) { if (e.target.tagName !== 'CANVAS') showCostBreakdownModal(); });

    var ageCard = q('#chart-card-age');
    if (ageCard) ageCard.addEventListener('click', function (e) { if (e.target.tagName !== 'CANVAS') showAgeBucketModal('All', 0, null); });

    var techCard = q('#chart-card-tech');
    if (techCard) techCard.addEventListener('click', function (e) { if (e.target.tagName !== 'CANVAS') showTechGroupModal(null); });

    var tsActive = q('#ts-active-block');
    if (tsActive) tsActive.addEventListener('click', function () { showTechGroupModal('Active'); });

    var tsIdle = q('#ts-idle-block');
    if (tsIdle) tsIdle.addEventListener('click', function () { showTechGroupModal('Idle'); });

    var tsTotal = q('#ts-total-block');
    if (tsTotal) tsTotal.addEventListener('click', function () { showTechGroupModal(null); });

    var viewJobs = q('#om-view-all-jobs');
    if (viewJobs) viewJobs.addEventListener('click', function () { frappe.set_route('List', 'Job Order'); });

    var viewTechs = q('#om-view-all-techs');
    if (viewTechs) viewTechs.addEventListener('click', function () { frappe.set_route('List', 'Employee'); });
  };

  loadTheme();
  setDate();
  attachEvents();
  refresh();

})();

style:
@import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Mono:wght@400;500&family=Inter:wght@300;400;500&display=swap');

.omeir-dashboard {
  --bg: #0b0d12;
  --surface: #111318;
  --surface2: #181b22;
  --border: #222530;
  --border-light: #2c3040;
  --text-primary: #eceef4;
  --text-secondary: #7a8299;
  --text-muted: #454d66;
  --accent-blue: #3b82f6;
  --accent-blue-glow: rgba(59,130,246,0.13);
  --accent-teal: #14b8a6;
  --accent-teal-glow: rgba(20,184,166,0.13);
  --accent-green: #22c55e;
  --accent-green-glow: rgba(34,197,94,0.11);
  --accent-amber: #f59e0b;
  --accent-amber-glow: rgba(245,158,11,0.11);
  --accent-coral: #f97316;
  --accent-coral-glow: rgba(249,115,22,0.11);
  --accent-indigo: #6366f1;
  --accent-indigo-glow: rgba(99,102,241,0.13);
  --accent-slate: #64748b;
  --accent-slate-glow: rgba(100,116,139,0.13);
  --danger: #ef4444;
  --danger-glow: rgba(239,68,68,0.11);
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,0.4);
  font-family: 'Inter', sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  padding: 24px 20px;
  min-height: 100vh;
  box-sizing: border-box;
  overflow-x: hidden;
  position: relative;
  transition: background 0.3s, color 0.3s;
}

.omeir-dashboard *, .omeir-dashboard *::before, .omeir-dashboard *::after { box-sizing: border-box; }

.omeir-dashboard.light-theme {
  --bg: #f0f2f7;
  --surface: #ffffff;
  --surface2: #f7f8fc;
  --border: #e2e6ef;
  --border-light: #cdd3e0;
  --text-primary: #1a2035;
  --text-secondary: #5a6480;
  --text-muted: #8e97b0;
  --accent-blue: #2563eb;
  --accent-blue-glow: rgba(37,99,235,0.09);
  --accent-teal: #0d9488;
  --accent-teal-glow: rgba(13,148,136,0.09);
  --accent-green: #16a34a;
  --accent-green-glow: rgba(22,163,74,0.09);
  --accent-amber: #d97706;
  --accent-amber-glow: rgba(217,119,6,0.09);
  --accent-coral: #ea580c;
  --accent-coral-glow: rgba(234,88,12,0.09);
  --accent-indigo: #4f46e5;
  --accent-indigo-glow: rgba(79,70,229,0.09);
  --accent-slate: #475569;
  --accent-slate-glow: rgba(71,85,105,0.09);
  --danger: #dc2626;
  --danger-glow: rgba(220,38,38,0.09);
  --shadow: 0 4px 20px rgba(0,0,0,0.07);
}

.om-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

.om-eyebrow {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.18em;
  color: var(--accent-amber);
  text-transform: uppercase;
  display: block;
  margin-bottom: 5px;
}

.om-title {
  font-family: 'Syne', sans-serif;
  font-size: 24px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: -0.02em;
  line-height: 1;
}

.om-header-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.om-date { font-family: 'DM Mono', monospace; font-size: 11px; color: var(--text-muted); }

.om-section-title {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  text-transform: uppercase;
  margin-bottom: 10px;
}

.om-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 500;
  padding: 7px 13px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.om-btn:hover { border-color: var(--accent-blue); color: var(--accent-blue); background: var(--accent-blue-glow); }
.om-btn.spinning svg { animation: om-spin 0.6s linear infinite; }
@keyframes om-spin { to { transform: rotate(360deg); } }

.om-filter-row { display: flex; align-items: center; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }

.om-filter-label {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  color: var(--text-muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-right: 4px;
}

.om-pill {
  padding: 5px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text-secondary);
  font-family: 'Inter', sans-serif;
  transition: all 0.18s;
  user-select: none;
}

.om-pill:hover { border-color: var(--accent-amber); color: var(--accent-amber); }
.om-pill.active { background: var(--accent-amber); color: #1a1200; border-color: var(--accent-amber); font-weight: 600; }

.om-kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.om-kpi-grid-5 { margin-bottom: 20px; }

@media (max-width: 1200px) { .om-kpi-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 800px)  { .om-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 500px)  { .om-kpi-grid { grid-template-columns: 1fr; } }

.om-kpi {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
  min-width: 0;
}

.om-kpi::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: var(--radius) var(--radius) 0 0;
}

.om-kpi.blue::after   { background: var(--accent-blue); }
.om-kpi.amber::after  { background: var(--accent-amber); }
.om-kpi.green::after  { background: var(--accent-green); }
.om-kpi.coral::after  { background: var(--accent-coral); }
.om-kpi.teal::after   { background: var(--accent-teal); }
.om-kpi.indigo::after { background: var(--accent-indigo); }
.om-kpi.slate::after  { background: var(--accent-slate); }

.om-kpi:hover { transform: translateY(-2px); border-color: var(--border-light); }
.om-kpi.blue:hover   { box-shadow: 0 6px 24px rgba(59,130,246,0.18); }
.om-kpi.amber:hover  { box-shadow: 0 6px 24px rgba(245,158,11,0.18); }
.om-kpi.green:hover  { box-shadow: 0 6px 24px rgba(34,197,94,0.16); }
.om-kpi.coral:hover  { box-shadow: 0 6px 24px rgba(249,115,22,0.16); }
.om-kpi.teal:hover   { box-shadow: 0 6px 24px rgba(20,184,166,0.16); }
.om-kpi.indigo:hover { box-shadow: 0 6px 24px rgba(99,102,241,0.18); }
.om-kpi.slate:hover  { box-shadow: 0 6px 24px rgba(100,116,139,0.15); }
.om-kpi:active { transform: translateY(0) scale(0.98); }

.om-kpi-label {
  font-size: 10px;
  font-weight: 500;
  color: var(--text-secondary);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.om-kpi-val {
  font-family: 'Syne', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
  letter-spacing: -0.02em;
  transition: all 0.4s;
}

.om-kpi-val.blue   { color: var(--accent-blue); }
.om-kpi-val.amber  { color: var(--accent-amber); }
.om-kpi-val.green  { color: var(--accent-green); }
.om-kpi-val.coral  { color: var(--accent-coral); }
.om-kpi-val.teal   { color: var(--accent-teal); }
.om-kpi-val.indigo { color: var(--accent-indigo); }
.om-kpi-val.slate  { color: var(--accent-slate); }

.om-kpi-sub {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  color: var(--text-muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.om-kpi-arrow {
  position: absolute;
  right: 10px;
  bottom: 10px;
  font-size: 13px;
  color: var(--text-muted);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s, transform 0.2s;
}

.om-kpi:hover .om-kpi-arrow { opacity: 1; transform: translateX(0); }

.om-charts-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 12px;
  width: 100%;
}

@media (max-width: 960px) { .om-charts-grid { grid-template-columns: 1fr; } }

.om-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
  transition: border-color 0.2s, transform 0.2s;
  min-width: 0;
  overflow: hidden;
}

.om-card.clickable { cursor: pointer; }
.om-card.clickable:hover { border-color: var(--border-light); transform: translateY(-1px); }

.om-card-title {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 10px;
}

.om-legend { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; }

.om-legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  color: var(--text-secondary);
  padding: 2px 4px;
  border-radius: 3px;
  transition: background 0.15s;
}

.om-legend-item:hover { background: var(--surface2); }

.om-lsq { width: 9px; height: 9px; border-radius: 2px; display: inline-block; flex-shrink: 0; }

.om-bottom-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 12px;
  width: 100%;
}

@media (max-width: 1000px) { .om-bottom-grid { grid-template-columns: 1fr; } }

.om-table-wrap { overflow-x: auto; }

.om-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  min-width: 460px;
}

.om-table th {
  text-align: left;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.om-table td { padding: 9px 10px; border-bottom: 1px solid var(--border); color: var(--text-primary); vertical-align: middle; }
.om-table tr:last-child td { border-bottom: none; }
.om-table tbody tr { cursor: pointer; transition: background 0.15s; }
.om-table tbody tr:hover td { background: var(--surface2); }

.om-job-link { font-family: 'DM Mono', monospace; font-size: 11px; color: var(--accent-blue); font-weight: 500; }

.om-vehicle-name { font-size: 12px; font-weight: 500; color: var(--text-primary); display: block; }
.om-vehicle-plate { font-family: 'DM Mono', monospace; font-size: 10px; color: var(--text-muted); display: block; }

.om-age-badge {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  padding: 3px 8px;
  border-radius: 4px;
  font-weight: 500;
  white-space: nowrap;
}

.age-ok   { background: rgba(34,197,94,0.12);  color: #22c55e; }
.age-warn { background: rgba(245,158,11,0.12); color: #f59e0b; }
.age-crit { background: rgba(239,68,68,0.12);  color: #ef4444; }

.om-type-badge {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  padding: 3px 8px;
  border-radius: 4px;
  background: var(--accent-blue-glow);
  color: var(--accent-blue);
}

.om-val-cell { font-family: 'DM Mono', monospace; font-size: 11px; color: var(--text-secondary); white-space: nowrap; }

.om-list-count {
  font-family: 'DM Mono', monospace;
  font-size: 10px;
  color: var(--text-muted);
}

.om-viewmore-btn {
  width: 100%;
  margin-top: 12px;
  padding: 10px;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--accent-blue);
  font-family: 'DM Mono', monospace;
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.18s;
  text-align: center;
}

.om-viewmore-btn:hover { background: var(--accent-blue-glow); border-color: var(--accent-blue); }

.om-tech-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 6px;
  border-radius: var(--radius-sm);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.15s;
}

.om-tech-row:last-child { border-bottom: none; }
.om-tech-row:hover { background: var(--surface2); }

.om-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  flex-shrink: 0;
  font-family: 'Syne', sans-serif;
}

.av-blue   { background: rgba(59,130,246,0.18);  color: #3b82f6; }
.av-teal   { background: rgba(20,184,166,0.18);  color: #14b8a6; }
.av-amber  { background: rgba(245,158,11,0.18);  color: #f59e0b; }
.av-gray   { background: rgba(120,130,160,0.15); color: #7a8299; }

.om-tech-info { flex: 1; min-width: 0; }
.om-tech-name { font-size: 12px; font-weight: 500; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.om-tech-job  { font-family: 'DM Mono', monospace; font-size: 10px; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.om-status-badge { font-family: 'DM Mono', monospace; font-size: 10px; padding: 3px 8px; border-radius: 4px; white-space: nowrap; flex-shrink: 0; }
.s-active { background: rgba(34,197,94,0.12);   color: #22c55e; }
.s-idle   { background: rgba(120,130,160,0.12); color: #7a8299; }

.om-tech-summary { display: flex; gap: 8px; margin-bottom: 12px; }

.om-ts-block {
  flex: 1;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 8px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.18s, transform 0.18s;
}

.om-ts-block:hover { border-color: var(--border-light); transform: translateY(-1px); }

.om-ts-val { font-family: 'Syne', sans-serif; font-size: 20px; font-weight: 700; display: block; line-height: 1.1; }
.om-ts-val.green { color: var(--accent-green); }
.om-ts-val.gray  { color: var(--text-muted); }

.om-ts-label { font-family: 'DM Mono', monospace; font-size: 10px; color: var(--text-muted); display: block; margin-top: 2px; }

.om-panel-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }

.om-panel-link {
  font-size: 11px;
  color: var(--accent-blue);
  cursor: pointer;
  font-weight: 500;
  font-family: 'DM Mono', monospace;
  text-decoration: none;
  transition: opacity 0.2s;
}

.om-panel-link:hover { opacity: 0.7; }

.om-loader { text-align: center; padding: 28px; color: var(--text-muted); font-family: 'DM Mono', monospace; font-size: 12px; }

.om-pulse { animation: om-pulse-anim 1.4s ease-in-out infinite; }
@keyframes om-pulse-anim { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }

.om-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.62);
  z-index: 9999;
  align-items: center;
  justify-content: center;
}

.om-modal-overlay.active { display: flex; animation: om-fade 0.18s ease; }
@keyframes om-fade { from { opacity: 0; } to { opacity: 1; } }

.om-modal-box {
  background: var(--surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  width: 580px;
  max-width: 94vw;
  max-height: 82vh;
  display: flex;
  flex-direction: column;
  animation: om-slide 0.22s cubic-bezier(0.4,0,0.2,1);
  box-shadow: 0 32px 80px rgba(0,0,0,0.4);
}

@keyframes om-slide { from { transform: translateY(16px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

.om-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--surface2);
  border-radius: var(--radius) var(--radius) 0 0;
  flex-shrink: 0;
}

.om-modal-title { font-family: 'Syne', sans-serif; font-size: 14px; font-weight: 700; color: var(--text-primary); }
.om-modal-subtitle { font-family: 'DM Mono', monospace; font-size: 10px; color: var(--text-muted); margin-top: 3px; }

.om-modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 16px;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition: all 0.15s;
  flex-shrink: 0;
  margin-left: 12px;
}

.om-modal-close:hover { background: var(--border); color: var(--text-primary); }

.om-modal-body { padding: 20px; overflow-y: auto; flex: 1; }

.om-detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 18px; }

.om-detail-block { background: var(--surface2); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; }

.om-detail-block-label { font-family: 'DM Mono', monospace; font-size: 9px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px; }
.om-detail-block-val   { font-size: 13px; font-weight: 500; color: var(--text-primary); }
.om-detail-block-val.mono { font-family: 'DM Mono', monospace; font-size: 12px; }

.om-section-label { font-family: 'DM Mono', monospace; font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 10px; padding-bottom: 6px; border-bottom: 1px solid var(--border); }

.om-cost-bar-row { margin-bottom: 12px; }
.om-cost-bar-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--text-secondary); margin-bottom: 5px; }
.om-cost-bar-label span:last-child { font-family: 'DM Mono', monospace; color: var(--text-primary); font-weight: 500; }
.om-cost-bar-track { height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; }
.om-cost-bar-fill  { height: 100%; border-radius: 3px; transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }

.om-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent-blue-glow);
  border: 1px solid var(--accent-blue);
  color: var(--accent-blue);
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.18s;
  margin-top: 6px;
}

.om-open-btn:hover { background: var(--accent-blue); color: #fff; }

.om-tech-detail-header { display: flex; align-items: center; gap: 14px; margin-bottom: 18px; }

.om-avatar-lg {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  font-weight: 700;
  flex-shrink: 0;
  font-family: 'Syne', sans-serif;
}

.om-tech-detail-name { font-family: 'Syne', sans-serif; font-size: 15px; font-weight: 700; color: var(--text-primary); }
.om-tech-detail-sub  { font-family: 'DM Mono', monospace; font-size: 11px; color: var(--text-muted); margin-top: 3px; }

.om-modal-list-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 6px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.12s, padding-left 0.12s;
}

.om-modal-list-row:last-child { border-bottom: none; }
.om-modal-list-row:hover { background: var(--surface2); padding-left: 10px; }

.om-modal-list-name { font-family: 'DM Mono', monospace; font-size: 11px; color: var(--accent-blue); font-weight: 500; }
.om-modal-list-sub  { font-size: 11px; color: var(--text-secondary); margin-top: 1px; }
.om-modal-list-right { text-align: right; flex-shrink: 0; margin-left: 12px; }
